 	if resp.StatusCode != http.StatusOK {
 		return "", &StatusError{Code: resp.StatusCode, Source: SourceToken}
 	}
-	body, err := io.ReadAll(resp.Body)
+	body, err := io.ReadAll(io.LimitReader(resp.Body, maxTokenResponse+1))
